import json
from pathlib import Path

data=json.loads(Path('benchmark/source_data.json').read_text())
mmr=data['maternal_mortality_timeseries']['data']
hexp=data['health_expenditure_gdp']['data']

h={(r['country'],r['year']): r['health_exp_pct_gdp'] for r in hexp}
points=[]
for r in mmr:
    points.append((r['country'],r['year'],h[(r['country'],r['year'])],r['mmr']))

order=['Ethiopia','India','Rwanda','Bangladesh','Nigeria','Cambodia','Peru','Nepal']
byyear={2005:[],2009:[],2013:[],2017:[],2021:[]}
for c,y,x,mm in points:
    byyear[y].append((order.index(c),x,mm,c))
for y in byyear:
    byyear[y].sort()
    print(y, ' '.join(f"[{x},{mm}]" for _,x,mm,_ in byyear[y]))
PY"}
